 opacity: 0.05;
 pointer-events: none;
}

.pulse-hero--healthy::before { background: radial-gradient(ellipse at 30% 50%, var(--cc-accent), transparent 70%); }
.pulse-hero--warning::before { background: radial-gradient(ellipse at 30% 50%, var(--cc-warning), transparent 70%); }
.pulse-hero--critical::before { background: radial-gradient(ellipse at 30% 50%, var(--cc-critical), transparent 70%); }

